import scala.collection.mutable.Builder; object Main { def appendAll[F <: Iterable[A], A](it:Iterator[F], b:Builder[A,F]):b.type={ while(it.hasNext) b ++= it.next(); b }; def all[A](xs:IterableOnce[List[A]]):Option[List[A]]={ val it=xs.iterator; if(it.isEmpty) None else Some(appendAll(it,List.newBuilder[A]).result()) }; def main(args:Array[String]):Unit={ println(all(List(List(1),List(2,3)))); println(all(List.empty[List[Int]])) } }
